 const hours=recordedSeconds(p)/3600;const attributes=[['Goblin composure',Math.min(100,Math.floor(hours/3+stats.credited_wins*2))],['Corporate resistance',Math.min(100,Math.floor(hours/6))],['Arcade gremlin',Math.min(100,Math.floor(stats.arena_best/360*100))]];
