DemoRepository.prototype.privacy=async function(allow){await this.world();this.data.v3.privacy={accepted:true,allow_nicotine:!!allow,notice_version:'2026-10-24-v3'};this.save();return {ok:true};};
DemoRepository.prototype.shift=async function(profile,kind){await this.world();const v=this.data.v3;if(v.shifts.some(s=>s.profile_id===profile&&Date.now()-Date.parse(s.created_at)<600000))throw new Error('You clocked in recently. Management noticed.');v.shifts.push({profile_id:profile,kind,created_at:new Date().toISOString()});this.save();return {ok:true};};
DemoRepository.prototype.deleteProfile=async function(id,name){const p=this.data.profiles.find(p=>p.id===id);if(!p||p.name!==name)throw new Error('Type the exact character name.');const rootIds=this.data.v2.posts.filter(p=>p.profile_id===id).map(p=>p.id);this.data.profiles=this.data.profiles.filter(p=>p.id!==id);this.data.events=this.data.events.filter(e=>e.profile_id!==id);this.data.v2.posts=this.data.v2.posts.filter(p=>p.profile_id!==id&&!rootIds.includes(p.parent_id));this.data.v2.challenges=this.data.v2.challenges.filter(c=>![c.challenger_id,c.opponent_id].includes(id));delete this.data.v2.ledger[id];delete this.data.v3.stats[id];this.data.v3.runs=this.data.v3.runs.filter(r=>r.profile_id!==id);this.data.v3.shifts=this.data.v3.shifts.filter(s=>s.profile_id!==id);this.data.v3.campaign.members=this.data.v3.campaign.members.filter(m=>m.profile_id!==id);this.save();return {ok:true};};
