container.innerHTML=`<section class="blacksite" aria-label="Blacksite 3D extraction game"><header class="bs-head"><div><small>KME ARCADE / REALTIME 3D</small><h2>BLACKSITE<span>THE LAST SHIFT</span></h2></div><div class="bs-header-actions"><button class="bs-sound" aria-label="Toggle game sound">Sound: off</button><button class="bs-pause" disabled>Pause</button><button class="bs-exit-mode" hidden>Exit game mode ✕</button></div></header><div class="bs-stage"><canvas class="bs-canvas" tabindex="0" aria-label="3D Blacksite arena. WASD move. Mouse aim, click shoot. Space dash. E parry. Q vent. F use lift."></canvas><div class="bs-vignette"></div><div class="bs-hud" hidden><div class="bs-mission"><span class="bs-floor"></span><strong class="bs-objective"></strong><small class="bs-notice"></small><meter class="bs-warden" min="0" max="100" value="100" aria-label="Warden integrity" hidden></meter></div><canvas class="bs-map" width="120" height="120" aria-label="Radar showing player, enemies and relays"></canvas><div class="bs-vitals"><label>INTEGRITY <b class="bs-hp-num">100</b><meter class="bs-hp" min="0" max="100" value="100"></meter></label><label>STAMINA<meter class="bs-stamina" min="0" max="100" value="100"></meter></label><label>WEAPON HEAT<meter class="bs-heat" min="0" max="100" value="0"></meter></label></div><div class="bs-haul"></div><div class="bs-kit"></div><div class="bs-channel" hidden><span>EXTRACTING · STAY STILL</span><progress max="5" value="0"></progress></div><div class="bs-touch"><div class="bs-joystick bs-move" role="group" aria-label="Movement joystick"><i></i><span>MOVE</span></div><div class="bs-touch-actions"><button class="bs-dash">DASH</button><button class="bs-parry">PARRY</button><button class="bs-vent">VENT</button><button class="bs-use">LIFT</button></div><div class="bs-joystick bs-aim" role="group" aria-label="Aim and shoot joystick"><i></i><span>AIM / FIRE</span></div></div></div><div class="bs-overlay"><small>SECURE CONNECTION / LOADING 3D ENGINE</small><h3>Entering<br>the blacksite.</h3></div></div><div class="bs-toolbar"><button class="bs-mode button secondary">⛶ Fullscreen / game mode</button><button class="bs-bank button" disabled>Extract · unlocks at 1:00</button></div><div class="bs-status" role="status">Loading the local 3D engine. No external game servers.</div><details class="bs-manual"><summary>Controls, enemy mechanics & extraction rules</summary><div><p><b>Desktop:</b> WASD / arrows move. Aim with mouse; hold click to fire. Space dash (brief invulnerability). E parries nearby projectiles back at enemies. Q vents heat. F uses the central lift after the warden dies. X starts or cancels extraction. Esc pauses.</p><p><b>Phone:</b> left stick moves; right stick aims and fires. Dash, parry, vent and lift buttons sit between them. Landscape gives a wider view. Game mode works even when native fullscreen is unavailable.</p><p><b>The job:</b> stand in each orange relay ring without firing for 1.8 seconds. After 45 seconds and all three relays, the warden arrives. Beat it, use the central lift and choose a temporary perk to descend. Shots hit cover. Lancers guard their front; flank or parry them. Red lines warn of charges and sniper shots. From floor three, sweeping lasers turn live after their warning. Mines mark the ground before detonating.</p><p><b>Greed has teeth:</b> deeper floors combine shielded chargers, fan volleys, locked sniper shots, mines and rotating beams. Staying on a floor beyond 100 seconds enrages its enemies. Dash and parry share stamina; holding fire overheats your weapon. Kills chain a four-second combo. Extraction takes five uninterrupted seconds standing still with your weapon down. Death, switching tabs or abandoning a pause loses 80% of unbanked score and capsules.</p><p><b>Rewards:</b> 1–15 minute arcade runs; boss finale runs remain at most five minutes. First two daily successful extractions deal up to 60 boss damage each, next twenty 1 chip each; later runs are cosmetic only. At most 12 cosmetic capsules per run. Loot grants no permanent power. Scores have timing bounds; this casual browser game cannot prove honest play.</p></div></details><div class="bs-loot"></div></section>`;
const $=sel=>container.querySelector(sel),box=$('.blacksite'),canvas=$('.bs-canvas'),overlay=$('.bs-overlay'),status=$('.bs-status');const text=t=>{status.textContent=t;};function show(html){overlay.hidden=false;overlay.innerHTML=html;}function tone(freq=200,d=.05){if(!soundOn)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();const osc=audio.createOscillator(),gain=audio.createGain();osc.type='triangle';osc.frequency.setValueAtTime(freq,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(freq/2,audio.currentTime+d);gain.gain.setValueAtTime(.05,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);osc.connect(gain).connect(audio.destination);osc.start();osc.stop(audio.currentTime+d);}catch{}}
