function frame(now){if(!alive||!active)return;const dt=Math.min(.1,(now-last)/1000);last=now;if(Date.now()-startedWall>=(o.mode==='finale'?300000:900000)){s.status='extracted';finish();return;}if(s.status==='lift'&&now-pauseTime>20000){s.status='extracted';finish();return;}if(paused){if(now-pauseTime>20000){retreat();return;}}else if(s.status==='playing'){input.mx=stick.x+(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0);input.mz=stick.z+(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0);if(Math.hypot(aimStick.x,aimStick.z)>.15){input.ax=aimStick.x;input.az=aimStick.z;input.fire=true;}else if(mouse.valid){const target=gfx.aim(mouse.x,mouse.y);if(target){input.ax=target.x-s.player.x;input.az=target.z-s.player.z;}input.fire=!!keys.Mouse;}else input.fire=false;input.vent=!!keys.KeyQ||!!keys.vent;input.interact=!!keys.KeyF||!!keys.use;input.bank=banking;const hp=s.player.hp,kills=s.kills;E.step(s,dt,input);if(s.player.hp<hp)tone(85,.15);if(s.kills>kills)tone(330,.08);if(input.fire&&s.player.fireCD>.18&&now-fireTone>160){tone(150,.04);fireTone=now;}if(s.status==='lift')lift();if(s.status==='dead'||s.status==='extracted'){gfx.update(s);hud();finish();return;}}
gfx.update(s);hud();if(!paused&&s.time-pulseAt>=15){pulseAt=s.time;pulse();}raf=requestAnimationFrame(frame);}
function joy(el,target){let id=null,origin=null;const knob=el.querySelector('i');on(el,'pointerdown',ev=>{if(!active||paused)return;ev.preventDefault();id=ev.pointerId;const r=el.getBoundingClientRect();origin={x:r.left+r.width/2,y:r.top+r.height/2,r:r.width*.32};el.setPointerCapture(id);point(ev);});function point(ev){if(ev.pointerId!==id)return;let x=(ev.clientX-origin.x)/origin.r,z=(ev.clientY-origin.y)/origin.r;const n=Math.max(1,Math.hypot(x,z));target.x=x/n;target.z=z/n;knob.style.transform='translate('+target.x*origin.r+'px,'+target.z*origin.r+'px)';}on(el,'pointermove',point);for(const type of['pointerup','pointercancel','lostpointercapture'])on(el,type,ev=>{if(ev.pointerId===id){id=null;target.x=target.z=0;knob.style.transform='translate(0,0)';}});}
