on(document,'keydown',e=>{if(!active||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||document.querySelector('dialog[open]'))return;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','KeyE','KeyQ','KeyF','KeyX','Escape','KeyW','KeyA','KeyS','KeyD'].includes(e.code))e.preventDefault();if(e.repeat)return;keys[e.code]=true;if(e.code==='Escape'){if(paused){paused=false;overlay.hidden=true;last=performance.now();}else pause();}if(paused)return;if(e.code==='Space'){E.dash(s,input);tone(280);}if(e.code==='KeyE'){E.pulse(s);tone(520,.1);}if(e.code==='KeyX'&&s.time>=60)banking=!banking;});on(document,'keyup',e=>keys[e.code]=false);on(window,'blur',()=>{clearInput();if(active)pause();});on(document,'visibilitychange',()=>{if(document.hidden&&active)retreat();});on(document,'fullscreenchange',()=>{if(!document.fullscreenElement&&gameMode){gameMode=false;box.classList.remove('bs-game-mode');document.documentElement.classList.remove('bs-mode-open');$('.bs-exit-mode').hidden=true;$('.bs-mode').textContent='⛶ Fullscreen / game mode';}});
on(container,'click',e=>{const b=e.target.closest('button');if(!b)return;if(b.classList.contains('bs-start'))start();if(b.classList.contains('bs-retry'))save();if(b.classList.contains('bs-discard')&&!busy){receipt=null;try{localStorage.removeItem(storageKey);}catch{}intro();}if(b.classList.contains('bs-again')){s=E.make(7);ticket=null;$('.bs-hud').hidden=true;intro();gfx?.update(s);}if(b.classList.contains('bs-mode'))setMode(!gameMode);if(b.classList.contains('bs-exit-mode'))setMode(false);if(b.classList.contains('bs-pause'))pause();if(b.classList.contains('bs-resume')){paused=false;overlay.hidden=true;last=performance.now();}if(b.classList.contains('bs-lift-bank')){s.status='extracted';finish();}if(b.classList.contains('bs-pause-bank')){paused=false;overlay.hidden=true;last=performance.now();if(s.time>=60)banking=true;else text('Extraction unlocks at one minute. Survive and stay mobile.');}if(b.classList.contains('bs-bank')&&active&&s.time>=60)banking=!banking;if(b.dataset.perk&&E.descend(s,b.dataset.perk)){overlay.hidden=true;last=performance.now();}if(b.classList.contains('bs-dash')){E.dash(s,input);tone(280);}if(b.classList.contains('bs-parry')){E.pulse(s);tone(520,.1);}if(b.classList.contains('bs-sound')){soundOn=!soundOn;b.textContent='Sound: '+(soundOn?'on':'off');if(soundOn)tone(400,.1);}});
