/* Keep the ballot and other games intact. The current cabinet is replaced by request. */
const v5DemoWorld=DemoRepository.prototype.world;
DemoRepository.prototype.world=async function(){const world=await v5DemoWorld.call(this);if(this.data.v4.current.game_key==='smoke-break'){Object.assign(this.data.v4.current,{game_key:'blacksite',game_name:'BLACKSITE: The Last Shift',build:'5.0.0'});this.save();}return world;};
const v5Scores=renderV3Scores;renderV3Scores=function(){v5Scores();if(arcadeKey()==='blacksite'&&!state.world.arcade.scores?.some(s=>s.game_key==='blacksite'))$('arena-scores').innerHTML=empty('New BLACKSITE leaderboard. Your earlier arcade records are preserved.');};
const v5DemoFinish=DemoRepository.prototype.extractionFinish;
DemoRepository.prototype.extractionFinish=async function(id,score,greed,capsules,extract=true){const r=this.data.v3.runs.find(r=>r.id===id);const result=await v5DemoFinish.call(this,id,score,greed,capsules,extract);if(extract&&r&&!r.v5recorded){r.v5recorded=true;r.game_key=this.data.v4.current.game_key;this.data.v4.scores??={};const k=r.profile_id+':'+r.game_key,prior=this.data.v4.scores[k]??={profile_id:r.profile_id,game_key:r.game_key,best:0,extracts:0};prior.best=Math.max(prior.best,score);prior.extracts++;this.save();}return result;};
const v5DemoWorldScores=DemoRepository.prototype.world;DemoRepository.prototype.world=async function(){const w=await v5DemoWorldScores.call(this);w.arcade.scores=[...w.arcade.scores,...Object.values(this.data.v4.scores||{})];return w;};
for(const Repo of[LiveRepository,DemoRepository]){const previous=Repo.prototype.deleteProfile;Repo.prototype.deleteProfile=async function(id,name){const result=await previous.call(this,id,name);try{for(const key of Object.keys(localStorage))if(key.startsWith('kme-blacksite-result-')&&key.includes('-'+id+'-'))localStorage.removeItem(key);}catch{}return result;};}

